    private int comIndx = 1;   // COM-INDX, of COM-CBSA-ENTRY
    private int bunIndx = 1;   // BUN-INDX, of BUN-CBSA-ENTRY
    private int comorbidIndex = 1;   // COMORBID-INDEX, of COMORBID-DATA

    public void run() {
        try {
            cocoonPerform(0, 14);
        } catch (CocoonStop s) {
            // GOBACK, STOP RUN or EXIT PROGRAM: the program ends
        }
    }

    /**
     * PERFORM from THRU thru: the paragraphs in order from the first to
     * the end of the last, falling through as COBOL does, and following
     * every GO TO wherever it leads - within the range or beyond it.
     */
    private void cocoonPerform(int from, int thru) {
        int p = from;
        while (true) {
            try {
                cocoonParagraph(p);
            } catch (CocoonGoTo g) {
                p = g.to;
                continue;
            }
            if (p == thru) {
                return;
            }
            p++;
            if (p >= 15) {
                throw COCOON_STOP;   // the end of the program
            }
        }
    }

    private void cocoonParagraph(int p) {
        switch (p) {
            case 0: p0100EnterDriver(); return;   // 0100-ENTER-DRIVER
            case 1: p0100ExitDriver(); return;   // 0100-EXIT-DRIVER
            case 2: p0500FindMsaWageAdjRate(); return;   // 0500-FIND-MSA-WAGE-ADJ-RATE
            case 3: p0500FindExit(); return;   // 0500-FIND-EXIT
            case 4: p0550NGetWageRate(); return;   // 0550-N-GET-WAGE-RATE
            case 5: p0550NExit(); return;   // 0550-N-EXIT
            case 6: p0700FindCompositeCbsaWi(); return;   // 0700-FIND-COMPOSITE-CBSA-WI
            case 7: p0700FindExit(); return;   // 0700-FIND-EXIT
            case 8: p0750GetCompCbsaRate(); return;   // 0750-GET-COMP-CBSA-RATE
            case 9: p0750CompExit(); return;   // 0750-COMP-EXIT
            case 10: p0800FindBundledCbsaWi(); return;   // 0800-FIND-BUNDLED-CBSA-WI
            case 11: p0800FindExit(); return;   // 0800-FIND-EXIT
            case 12: p0820SearchChildHospTable(); return;   // 0820-SEARCH-CHILD-HOSP-TABLE
            case 13: p0850GetBundledCbsaRate(); return;   // 0850-GET-BUNDLED-CBSA-RATE
            case 14: p0850BundledExit(); return;   // 0850-BUNDLED-EXIT
            default: throw COCOON_STOP;
        }
    }

