    /** 0800-FIND-BUNDLED-CBSA-WI */
    private void p0800FindBundledCbsaWi() {
        if (pSpecPymtInd.value().compareTo("1") == 0) {
            bunCbsaWIndex.store(pSpecWageIndx.value());
            cocoonGoTo(11);   // GO TO 0800-FIND-EXIT
        }
        if (CobolText.compareAlnum(bThruDate.value(), "20141231") > 0 && CobolText.compareAlnum(bThruDate.value(), "20160101") < 0) {
            childHospSwiFoundSwitch.store("N");
            childHospTableSub.store(new BigDecimal("1"));
            while (true) {
                p0820SearchChildHospTable();
                if (childHospSwiFoundSwitch.value().compareTo("Y") == 0 || childHospTableSub.value().compareTo(totalNumOfChildHosp.value()) == 0) break;
                childHospTableSub.store(childHospTableSub.value().add(new BigDecimal("1")));
            }
            if (childHospSwiFoundSwitch.value().compareTo("Y") == 0) {
                bunCbsaWIndex.store(childHospSwi[childHospTableSub.value().intValue() - 1].value());
                cocoonGoTo(11);   // GO TO 0800-FIND-EXIT
            }
        }
        bunSub.store(bunMaxDate.value());
        bThruYearCode.store(new CobolText(r_BILL_NEW_DATA, 26, 2).value());
        bThruYearCode.store(bThruYearCode.value().subtract(new BigDecimal("10")));
        while (!(bThruDate.value().compareTo(bunDate[bunSub.value().intValue() - 1].value()) >= 0)) {
            bunSub.store(bunSub.value().subtract(new BigDecimal("1")));
        }
        {   // SEARCH ALL BUN-CBSA-ENTRY, as GnuCOBOL runs it
            int cocoonHead3 = 0, cocoonTail3 = 505 + 1;
            while (true) {
                if (cocoonHead3 >= cocoonTail3 - 1) {
                    if (mainframePcSwitch.value().compareTo(dsErrorCode.value()) == 0) {
                        ppsRtc.store(new BigDecimal("60"));
                        cocoonGoTo(11);   // GO TO 0800-FIND-EXIT
                    } else {
                        ppsRtc.store(new BigDecimal("61"));
                        cocoonGoTo(11);   // GO TO 0800-FIND-EXIT
                    }
                    break;
                }
                bunIndx = (cocoonHead3 + cocoonTail3) / 2;
                int cocoonRet3 = bunCbsaValue[bunIndx - 1].value().compareTo(pGeoCbsa.value());
                if (cocoonRet3 == 0) {
                    wSub3.store(bunPtr[bunIndx - 1].value());
                    cocoonPerform(13, 14);   // PERFORM 0850-GET-BUNDLED-CBSA-RATE THRU 0850-BUNDLED-EXIT
                    break;
                }
                if (cocoonRet3 < 0) {
                    cocoonHead3 = bunIndx;
                } else {
                    cocoonTail3 = bunIndx;
                }
            }
        }
        if (CobolText.compareAlnum(bThruDate.value(), "20200930") > 0) {
            if (pSuppWiInd.value().compareTo("1") == 0) {
                if (pSuppWi.value().compareTo(new BigDecimal("0")) > 0) {
                    try {   // a zero divisor stores nothing, as in COBOL
                        hEsrdSuppWiRatio.store(CobolDecimal.divide(bunCbsaWIndex.value().subtract(pSuppWi.value()), pSuppWi.value()));
                        // TRUNCATES: the expression produces up to 2 integer digits and H-ESRD-SUPP-WI-RATIO holds 1. The high-order digits are lost, as in the original.
                    } catch (CobolDecimal.ZeroDivide cocoonZeroDivide) {
                        // every receiver keeps what it held
                    }
                    if (hEsrdSuppWiRatio.value().compareTo(new BigDecimal("-0.05")) < 0) {
                        bunCbsaWIndex.storeRounded(pSuppWi.value().multiply(new BigDecimal("0.95")));
                    }
                    cocoonGoTo(11);   // GO TO 0800-FIND-EXIT
                } else {
                    ppsRtc.store(new BigDecimal("60"));
                    cocoonGoTo(11);   // GO TO 0800-FIND-EXIT
                }
            }
        }
    }

